        # Mode must appear at least twice and be unique
        # Try all possible lists with numbers between 1 and n+2
        for a in range(1, n+3):
            for b in range(a, n+3):
                for c in range(b, n+3):
                    for d in range(c, n+3):
                        for e in range(d, n+3):
                            lst = [a, b, c, d, e]
                            # Check median
