                            s = sum(lst)
                            if Rational(s, 5) != mean:
                                continue
                            # Check unique mode
                            counts = {x: lst.count(x) for x in set(lst)}
                            max_count = max(counts.values())
                            mode_candidates = [k for k, v in counts.items() if v == max_count]
                            if len(mode_candidates) != 1 or mode_candidates[0] != mode or max_count < 2:
